SELECT DATE_FORMAT(ss.sale_date, 'yyyy-MM') AS sale_month, CASE WHEN YEAR(ss.sale_date) < 2024 THEN 'before_2024' WHEN YEAR(ss.sale_date) = 2024 THEN '2024' ELSE 'after_2024' END AS sale_cohort, MIN(i.quantity) AS min_quantity FROM inventory i LEFT JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id GROUP BY DATE_FORMAT(ss.sale_date, 'yyyy-MM'), CASE WHEN YEAR(ss.sale_date) < 2024 THEN 'before_2024' WHEN YEAR(ss.sale_date) = 2024 THEN '2024' ELSE 'after_2024' END ORDER BY 3, sale_month, sale_cohort LIMIT 5
